const raw = $input.first().json;
const d = raw.body || raw;

const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><style>body{font-family:Arial,sans-serif;background:#f4f4f4;margin:0;padding:0;}.wrapper{max-width:560px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.10);}.header{background:#1a1a2e;padding:24px 32px;}.header img{height:44px;object-fit:contain;}.body{padding:32px;color:#333;font-size:15px;line-height:1.7;}.footer{background:#f5f0e8;padding:16px 32px;text-align:center;font-size:11px;color:#888;border-top:1px solid #e5e0d8;}.footer a{color:#C9922A;text-decoration:none;}</style></head><body><div class="wrapper"><div class="header"><img src="https://yellowfeather.netlify.app/logo-landscape.png" alt="Yellow Feather Books"/></div><div class="body"><p>Hello ${d.toName || 'there'},</p><p>Please find attached your invoice <strong>${d.invoiceNumber}</strong> from Yellow Feather Books.</p><p>For any queries, reach us at <a href="mailto:bookstore@yellowfeatherbookstore.com" style="color:#C9922A;">bookstore@yellowfeatherbookstore.com</a> or +91 94004 48000.</p><p style="margin-top:24px;">Warm regards,<br/><strong>Team Yellow Feather</strong></p></div><div class="footer">Yellow Feather Books &nbsp;·&nbsp; <a href="mailto:bookstore@yellowfeatherbookstore.com">bookstore@yellowfeatherbookstore.com</a></div></div></body></html>`;

return [{
  json: { to: d.to, toName: d.toName || '', invoiceNumber: d.invoiceNumber, subject: `Invoice ${d.invoiceNumber} — Yellow Feather Books`, html },
  binary: {
    data: {
      data: d.pdfBase64,
      mimeType: 'application/pdf',
      fileName: d.filename || `${d.invoiceNumber || 'invoice'}.pdf`
    }
  }
}];
